			/*
			 * 사례정보 항목 check
			 */
			function checkCaseInfo() {
			    
			    var dsList = app.lookup("dsList");
			    
			    if (dsList.getRowCount() == 0) {
			        util.Msg.alert(app, "보호처분정보는 필수 입력입니다.");
			        return false;
			    }
			    
			    if (!util.validate(app, "grdList")) return false;
			    
			    var dsList = app.lookup("dsList");
			    for (var i = 0; i < dsList.getRowCount(); i++ ) {
			            
			        if (dsList.getValue(i, "PRTCTN_DSPS_XTND_APLCNT_SE_CD") == "04" &&
			            ValueUtil.isNull(dsList.getValue(i, "XTND_APLY_COURT_SE_CD"))) {
			            util.Msg.alert(app, "연장법원신청을 등록해 주세요.");
			            return false;
			        }

			        if (dsList.getValue(i, "PRTCTN_DSPS_XTND_APLCNT_SE_CD") == "99" &&
			            ValueUtil.isNull(dsList.getValue(i, "PRTCTN_DSPS_XTND_APLCNT_ETC_CN"))) {
			            util.Msg.alert(app, "연장신청자 기타(텍스트) 등록해 주세요.");
			            return false;
			        }

			        if (!ValueUtil.isNull(dsList.getValue(i, "PRTCTN_DSPS_XTND_APLCNT_SE_CD")) &&
			            ValueUtil.isNull(dsList.getValue(i, "PRTCTN_DSPS_XTND_CS_SE_CD"))) {
			            util.Msg.alert(app, "연장사유를 등록해 주세요.");
			            return false;
			        }

			        if (dsList.getValue(i, "PRTCTN_DSPS_XTND_CS_SE_CD") == "99" &&
			            ValueUtil.isNull(dsList.getValue(i, "PRTCTN_DSPS_XTND_CS_ETC_CN"))) {
			            util.Msg.alert(app, "연장사유 기타(텍스트)를 등록해 주세요.");
			            return false;
			        }

			    }
			    
			    return true;
			}

			/*
			 * 위기스트리닝 dmCrisisScrennList -> dsCrisisScoreList
			 */
			function setCrisisScore() {
			    
			    var dsCrisisScoreList = app.lookup("dsCrisisScoreList");
			    var dmCrisisScrennList = app.lookup("dmCrisisScrennList");
			    var dmColumn = dmCrisisScrennList.getColumnNames();
			    var j = 0;
			    for(var i = 0; i < dmColumn.length; i++){
			        if(!ValueUtil.isNull(dmCrisisScrennList.getValue(dmColumn[i]))){
			            var newRowData = {
			                "CASE_MNG_NO": caseMngNo,
			                "CASE_MNG_ODRNO": caseMngOdrno,
			                "CRISIS_SCRENN_SCORE_SE_CD": dmColumn[i],
			                "CRISIS_SCRENN_EVL_SCORE": dmCrisisScrennList.getValue(dmColumn[i])
			            };
			            
			            dsCrisisScoreList.insertRowData(j, false, newRowData);
			            j++;
			        }
			    }
			    
			}

